-- Cabin Crew · Afirmações do perfil comportamental (estilo OPQ)
-- Rode depois da migração 0023_opq.sql. Pode rodar mais de uma vez (atualiza, não duplica).
-- Gerado por scripts/opq-afirmacoes.py
-- 392 afirmações (248 da Horsky + 144 novas), ativas por traço:
--   Comunicação               10 positivas ·  10 negativas
--   Disciplina e Segurança    13 positivas ·  12 negativas
--   Empatia                   10 positivas ·  10 negativas
--   Flexibilidade             10 positivas ·  10 negativas
--   Integridade               10 positivas ·  10 negativas
--   Liderança                 52 positivas ·  47 negativas
--   Organização               10 positivas ·  10 negativas
--   Orientação a Serviço      10 positivas ·  10 negativas
--   Proatividade              10 positivas ·  10 negativas
--   Resiliência               10 positivas ·  10 negativas
--   Trabalho em Equipe        53 positivas ·  52 negativas

on conflict (codigo) do update set traco = excluded.traco, direcao = excluded.direcao,
  texto = excluded.texto, ativo = excluded.ativo, origem = excluded.origem;

select traco, count(*) filter (where direcao = 1) as positivas, count(*) filter (where direcao = -1) as negativas
from opq_afirmacoes where ativo group by traco order by traco;
